<?php
$q=get_string('q');$where='1=1';$params=[];if($q!==''){$like='%'.$q.'%';$where='(a.action_type LIKE ? OR a.table_name LIKE ? OR a.record_id LIKE ? OR u.full_name LIKE ?)';$params=[$like,$like,$like,$like];}$stmt=db()->prepare("SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.user_id=a.user_id WHERE $where ORDER BY a.created_at DESC LIMIT 500");$stmt->execute($params);$rows=$stmt->fetchAll();
?>
<div class="page-header"><div><h2>Audit logs</h2><p>Trace sensitive system actions and record changes.</p></div></div><div class="card"><div class="card-header"><div><h3>Activity history</h3><p>Latest 500 matching events.</p></div><form method="get" class="actions"><input type="hidden" name="page" value="audit"><input class="input" name="q" value="<?=e($q)?>" placeholder="Action, table, record or user"><button class="btn btn-light">Search</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Record</th><th>IP</th><th>Change summary</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=format_date($r['created_at'],'d M Y, h:i:s A')?></td><td><?=e($r['full_name']??'System')?></td><td><span class="badge badge-info"><?=e($r['action_type'])?></span></td><td><?=e(($r['table_name']??'—').' #'.($r['record_id']??'—'))?></td><td><?=e($r['ip_address']??'—')?></td><td><details><summary>View data</summary><pre style="white-space:pre-wrap;max-width:420px;font-size:11px"><?=e($r['new_data']??$r['old_data']??'No payload')?></pre></details></td></tr><?php endforeach;?></tbody></table></div></div>
